@block PandaIK begin
    # 1 kHz analytical inverse kinematics of the Panda flange (sampled firmware, D28), the
    # case-consistent geometric solver of Y. He and S. Liu, "Analytical Inverse Kinematics for
    # Franka Emika Panda - a Geometrical Solver for 7-DOF Manipulators with Unconventional Design",
    # ICCMA 2021 (github.com/ffall007/franka_analytical_ik, Apache-2.0), re-derived for the
    # flange frame (d7e = 0.107 m, no hand rotation). Generated by design/build_library.py; the
    # Python twin is `panda.ik_flange` (validated by an FK round trip at 20000 poses).
    #
    # Redundancy: q7 is held at `q7r`. Branch: the shoulder sign (q2 < 0) and the wrist case
    # ((H - O6) x (O2 - O6) . z6 <= 0) are those of the measured joint angles, so the solution
    # stays on the branch the arm is on. No solution (target out of reach, or a joint limit):
    # the outputs keep the last valid solution and `flag` names the cause (1 unreachable,
    # 2..7 the joint (code - 1) whose limit is violated; 0 = solved).
    @parameters begin
        q7r::Real = 0.7853981633974483, [unit = "rad", description = "Redundancy parameter: the q7 of the solution"]
    end
    @inputs begin
        g::Vec{7}
        q1::Real, [unit = "rad"]
        q2::Real, [unit = "rad"]
        q3::Real, [unit = "rad"]
        q4::Real, [unit = "rad"]
        q5::Real, [unit = "rad"]
        q6::Real, [unit = "rad"]
    end
    @outputs begin
        qr1::Real = 0.0, [unit = "rad"]
        qr2::Real = -0.7853981633974483, [unit = "rad"]
        qr3::Real = 0.0, [unit = "rad"]
        qr4::Real = -2.356194490192345, [unit = "rad"]
        qr5::Real = 0.0, [unit = "rad"]
        qr6::Real = 1.5707963267948966, [unit = "rad"]
        qr7::Real = 0.7853981633974483, [unit = "rad"]
        flag::Real = 0.0, [unit = "1", description = "0 solved; else the cause (outputs held)"]
    end
    @discrete Ts = 0.001 begin
        code = 0.0
        # forward kinematics of the measured angles (for the branch)
        c1 = cos(q1)
        s1 = sin(q1)
        A1_11 = 1.0
        A1_12 = (1.0 * 0.0 + 0.0 * 0.0)
        A1_13 = (0.0 * 0.0 + 1.0 * 0.0)
        A1_21 = 0.0
        A1_22 = (1.0 * 1.0 + 0.0 * 0.0)
        A1_23 = (0.0 * 1.0 + 1.0 * 0.0)
        A1_31 = 0.0
        A1_32 = (1.0 * 0.0 + 0.0 * 1.0)
        A1_33 = (0.0 * 0.0 + 1.0 * 1.0)
        o1_1 = 0.0 + 0.333 * 0.0
        o1_2 = 0.0 + 0.333 * 0.0
        o1_3 = 0.0 + 0.333 * 1.0
        R1_11 = c1 * A1_11 + s1 * A1_12
        R1_12 = -s1 * A1_11 + c1 * A1_12
        R1_13 = A1_13
        R1_21 = c1 * A1_21 + s1 * A1_22
        R1_22 = -s1 * A1_21 + c1 * A1_22
        R1_23 = A1_23
        R1_31 = c1 * A1_31 + s1 * A1_32
        R1_32 = -s1 * A1_31 + c1 * A1_32
        R1_33 = A1_33
        c2 = cos(q2)
        s2 = sin(q2)
        A2_11 = R1_11
        A2_12 = (0.0 * R1_12 + -1.0 * R1_13)
        A2_13 = (1.0 * R1_12 + 0.0 * R1_13)
        A2_21 = R1_21
        A2_22 = (0.0 * R1_22 + -1.0 * R1_23)
        A2_23 = (1.0 * R1_22 + 0.0 * R1_23)
        A2_31 = R1_31
        A2_32 = (0.0 * R1_32 + -1.0 * R1_33)
        A2_33 = (1.0 * R1_32 + 0.0 * R1_33)
        o2_1 = o1_1
        o2_2 = o1_2
        o2_3 = o1_3
        R2_11 = c2 * A2_11 + s2 * A2_12
        R2_12 = -s2 * A2_11 + c2 * A2_12
        R2_13 = A2_13
        R2_21 = c2 * A2_21 + s2 * A2_22
        R2_22 = -s2 * A2_21 + c2 * A2_22
        R2_23 = A2_23
        R2_31 = c2 * A2_31 + s2 * A2_32
        R2_32 = -s2 * A2_31 + c2 * A2_32
        R2_33 = A2_33
        c3 = cos(q3)
        s3 = sin(q3)
        A3_11 = R2_11
        A3_12 = (0.0 * R2_12 + 1.0 * R2_13)
        A3_13 = (-1.0 * R2_12 + 0.0 * R2_13)
        A3_21 = R2_21
        A3_22 = (0.0 * R2_22 + 1.0 * R2_23)
        A3_23 = (-1.0 * R2_22 + 0.0 * R2_23)
        A3_31 = R2_31
        A3_32 = (0.0 * R2_32 + 1.0 * R2_33)
        A3_33 = (-1.0 * R2_32 + 0.0 * R2_33)
        o3_1 = o2_1 + -0.316 * R2_12
        o3_2 = o2_2 + -0.316 * R2_22
        o3_3 = o2_3 + -0.316 * R2_32
        R3_11 = c3 * A3_11 + s3 * A3_12
        R3_12 = -s3 * A3_11 + c3 * A3_12
        R3_13 = A3_13
        R3_21 = c3 * A3_21 + s3 * A3_22
        R3_22 = -s3 * A3_21 + c3 * A3_22
        R3_23 = A3_23
        R3_31 = c3 * A3_31 + s3 * A3_32
        R3_32 = -s3 * A3_31 + c3 * A3_32
        R3_33 = A3_33
        c4 = cos(q4)
        s4 = sin(q4)
        A4_11 = R3_11
        A4_12 = (0.0 * R3_12 + 1.0 * R3_13)
        A4_13 = (-1.0 * R3_12 + 0.0 * R3_13)
        A4_21 = R3_21
        A4_22 = (0.0 * R3_22 + 1.0 * R3_23)
        A4_23 = (-1.0 * R3_22 + 0.0 * R3_23)
        A4_31 = R3_31
        A4_32 = (0.0 * R3_32 + 1.0 * R3_33)
        A4_33 = (-1.0 * R3_32 + 0.0 * R3_33)
        o4_1 = o3_1 + 0.0825 * R3_11
        o4_2 = o3_2 + 0.0825 * R3_21
        o4_3 = o3_3 + 0.0825 * R3_31
        R4_11 = c4 * A4_11 + s4 * A4_12
        R4_12 = -s4 * A4_11 + c4 * A4_12
        R4_13 = A4_13
        R4_21 = c4 * A4_21 + s4 * A4_22
        R4_22 = -s4 * A4_21 + c4 * A4_22
        R4_23 = A4_23
        R4_31 = c4 * A4_31 + s4 * A4_32
        R4_32 = -s4 * A4_31 + c4 * A4_32
        R4_33 = A4_33
        c5 = cos(q5)
        s5 = sin(q5)
        A5_11 = R4_11
        A5_12 = (0.0 * R4_12 + -1.0 * R4_13)
        A5_13 = (1.0 * R4_12 + 0.0 * R4_13)
        A5_21 = R4_21
        A5_22 = (0.0 * R4_22 + -1.0 * R4_23)
        A5_23 = (1.0 * R4_22 + 0.0 * R4_23)
        A5_31 = R4_31
        A5_32 = (0.0 * R4_32 + -1.0 * R4_33)
        A5_33 = (1.0 * R4_32 + 0.0 * R4_33)
        o5_1 = o4_1 + -0.0825 * R4_11 + 0.384 * R4_12
        o5_2 = o4_2 + -0.0825 * R4_21 + 0.384 * R4_22
        o5_3 = o4_3 + -0.0825 * R4_31 + 0.384 * R4_32
        R5_11 = c5 * A5_11 + s5 * A5_12
        R5_12 = -s5 * A5_11 + c5 * A5_12
        R5_13 = A5_13
        R5_21 = c5 * A5_21 + s5 * A5_22
        R5_22 = -s5 * A5_21 + c5 * A5_22
        R5_23 = A5_23
        R5_31 = c5 * A5_31 + s5 * A5_32
        R5_32 = -s5 * A5_31 + c5 * A5_32
        R5_33 = A5_33
        c6 = cos(q6)
        s6 = sin(q6)
        A6_11 = R5_11
        A6_12 = (0.0 * R5_12 + 1.0 * R5_13)
        A6_13 = (-1.0 * R5_12 + 0.0 * R5_13)
        A6_21 = R5_21
        A6_22 = (0.0 * R5_22 + 1.0 * R5_23)
        A6_23 = (-1.0 * R5_22 + 0.0 * R5_23)
        A6_31 = R5_31
        A6_32 = (0.0 * R5_32 + 1.0 * R5_33)
        A6_33 = (-1.0 * R5_32 + 0.0 * R5_33)
        o6_1 = o5_1
        o6_2 = o5_2
        o6_3 = o5_3
        R6_11 = c6 * A6_11 + s6 * A6_12
        R6_12 = -s6 * A6_11 + c6 * A6_12
        R6_13 = A6_13
        R6_21 = c6 * A6_21 + s6 * A6_22
        R6_22 = -s6 * A6_21 + c6 * A6_22
        R6_23 = A6_23
        R6_31 = c6 * A6_31 + s6 * A6_32
        R6_32 = -s6 * A6_31 + c6 * A6_32
        R6_33 = A6_33
        h1 = o4_1 - 0.0825 * R4_11
        h2 = o4_2 - 0.0825 * R4_21
        h3 = o4_3 - 0.0825 * R4_31
        a1 = h1 - o6_1
        a2 = h2 - o6_2
        a3 = h3 - o6_3
        b1 = -o6_1
        b2 = -o6_2
        b3 = 0.333 - o6_3
        case6 = (a2 * b3 - a3 * b2) * R6_13 + (a3 * b1 - a1 * b3) * R6_23 + (a1 * b2 - a2 * b1) * R6_33
        # target rotation (columns x_f, y_f, z_f) and position
        nq = g[1] * g[1] + g[2] * g[2] + g[3] * g[3] + g[4] * g[4]
        r11 = (g[1] * g[1] + g[2] * g[2] - g[3] * g[3] - g[4] * g[4]) / nq
        r12 = 2.0 * (g[2] * g[3] - g[1] * g[4]) / nq
        r13 = 2.0 * (g[2] * g[4] + g[1] * g[3]) / nq
        r21 = 2.0 * (g[2] * g[3] + g[1] * g[4]) / nq
        r22 = (g[1] * g[1] - g[2] * g[2] + g[3] * g[3] - g[4] * g[4]) / nq
        r23 = 2.0 * (g[3] * g[4] - g[1] * g[2]) / nq
        r31 = 2.0 * (g[2] * g[4] - g[1] * g[3]) / nq
        r32 = 2.0 * (g[3] * g[4] + g[1] * g[2]) / nq
        r33 = (g[1] * g[1] - g[2] * g[2] - g[3] * g[3] + g[4] * g[4]) / nq
        # wrist points: p7 = p - d7e z_f, x6 = R_f (cos q7, -sin q7, 0), p6 = p7 - a7 x6
        c7 = cos(q7r)
        s7 = sin(q7r)
        x61 = r11 * c7 - r12 * s7
        x62 = r21 * c7 - r22 * s7
        x63 = r31 * c7 - r32 * s7
        nx = sqrt(x61 * x61 + x62 * x62 + x63 * x63)
        x61 = x61 / nx
        x62 = x62 / nx
        x63 = x63 / nx
        p61 = g[5] - 0.107 * r13 - 0.088 * x61
        p62 = g[6] - 0.107 * r23 - 0.088 * x62
        p63 = g[7] - 0.107 * r33 - 0.088 * x63
        # q4 from the triangle O2-O4-O6
        v1 = p61
        v2 = p62
        v3 = p63 - 0.333
        ll26 = v1 * v1 + v2 * v2 + v3 * v3
        l26 = max(sqrt(ll26), 1.0e-9)
        if 0.7193542034041307 < l26 || 0.3265918706887849 + l26 < 0.39276233271534583 || l26 + 0.39276233271534583 < 0.3265918706887849
            code = 1.0
        end
        th246 = acos(clamp((0.2609245 - ll26) / 0.25654596995519147, -1.0, 1.0))
        k4 = th246 + -3.6085950772428044
        if code == 0.0 && (k4 <= -3.0718 || k4 >= -0.0698)
            code = 5.0
        end
        # q6
        th462 = acos(clamp((ll26 + 0.04760000000000002) / (2.0 * l26 * 0.39276233271534583), -1.0, 1.0))
        th26h = 0.21162680876562978 + th462
        d26 = -l26 * cos(th26h)
        z61 = r23 * x63 - r33 * x62
        z62 = r33 * x61 - r13 * x63
        z63 = r13 * x62 - r23 * x61
        y61 = z62 * x63 - z63 * x62
        y62 = z63 * x61 - z61 * x63
        y63 = z61 * x62 - z62 * x61
        ny = sqrt(y61 * y61 + y62 * y62 + y63 * y63)
        nz = sqrt(z61 * z61 + z62 * z62 + z63 * z63)
        y61 = y61 / ny
        y62 = y62 / ny
        y63 = y63 / ny
        z61 = z61 / nz
        z62 = z62 / nz
        z63 = z63 / nz
        u1 = -(x61 * v1 + x62 * v2 + x63 * v3)
        u2 = -(y61 * v1 + y62 * v2 + y63 * v3)
        phi6 = atan(u2, u1)
        theta6 = asin(clamp(d26 / sqrt(u1 * u1 + u2 * u2), -1.0, 1.0))
        if case6 <= 0.0
            k6 = 3.141592653589793 - theta6 - phi6
        else
            k6 = theta6 - phi6
        end
        if k6 <= -0.0175
            k6 = k6 + 6.283185307179586
        elseif k6 >= 3.7525
            k6 = k6 - 6.283185307179586
        end
        if code == 0.0 && (k6 <= -0.0175 || k6 >= 3.7525)
            code = 7.0
        end
        # q1, q2 from the shoulder-to-P direction
        thp26 = 3.396968268477175 - th462 - th246
        thp = 3.141592653589793 - thp26 - th26h
        lp6 = l26 * sin(thp26) / sin(thp)
        z51 = x61 * sin(k6) + y61 * cos(k6)
        z52 = x62 * sin(k6) + y62 * cos(k6)
        z53 = x63 * sin(k6) + y63 * cos(k6)
        w1 = p61 - lp6 * z51
        w2 = p62 - lp6 * z52
        w3 = p63 - lp6 * z53 - 0.333
        l2p = sqrt(w1 * w1 + w2 * w2 + w3 * w3)
        if sqrt(w1 * w1 + w2 * w2) < 1.0e-9 * l2p
            k1 = q1
            k2 = 0.0
        else
            k1 = atan(w2, w1)
            k2 = acos(clamp(w3 / l2p, -1.0, 1.0))
            if q2 < 0.0
                if k1 < 0.0
                    k1 = k1 + 3.141592653589793
                else
                    k1 = k1 - 3.141592653589793
                end
                k2 = -k2
            end
        end
        if code == 0.0 && (k1 <= -2.8973 || k1 >= 2.8973)
            code = 2.0
        end
        if code == 0.0 && (k2 <= -1.7628 || k2 >= 1.7628)
            code = 3.0
        end
        # q3: frame 3 from V2P and V26
        z31 = w1 / l2p
        z32 = w2 / l2p
        z33 = w3 / l2p
        t1 = -(v2 * w3 - v3 * w2)
        t2 = -(v3 * w1 - v1 * w3)
        t3 = -(v1 * w2 - v2 * w1)
        nt = sqrt(t1 * t1 + t2 * t2 + t3 * t3)
        y31 = t1 / nt
        y32 = t2 / nt
        y33 = t3 / nt
        x31 = y32 * z33 - y33 * z32
        x32 = y33 * z31 - y31 * z33
        x33 = y31 * z32 - y32 * z31
        ck1 = cos(k1)
        sk1 = sin(k1)
        ck2 = cos(k2)
        sk2 = sin(k2)
        e1 = ck1 * ck2 * x31 + sk1 * ck2 * x32 - sk2 * x33
        e3 = -sk1 * x31 + ck1 * x32
        k3 = atan(e3, e1)
        if code == 0.0 && (k3 <= -2.8973 || k3 >= 2.8973)
            code = 4.0
        end
        # q5
        vh1 = 0.316 * z31 + 0.0825 * x31 - p61 + 0.384 * z51
        vh2 = 0.316 * z32 + 0.0825 * x32 - p62 + 0.384 * z52
        vh3 = 0.333 + 0.316 * z33 + 0.0825 * x33 - p63 + 0.384 * z53
        ck6 = cos(k6)
        sk6 = sin(k6)
        f1 = (ck6 * x61 - sk6 * y61) * vh1 + (ck6 * x62 - sk6 * y62) * vh2 + (ck6 * x63 - sk6 * y63) * vh3
        f2 = -(z61 * vh1 + z62 * vh2 + z63 * vh3)
        k5 = -atan(f2, f1)
        if code == 0.0 && (k5 <= -2.8973 || k5 >= 2.8973)
            code = 6.0
        end
        if code == 0.0
            qr1 = k1
            qr2 = k2
            qr3 = k3
            qr4 = k4
            qr5 = k5
            qr6 = k6
            qr7 = q7r
        end
        flag = code
    end
end
